import{_ as a,a0 as s,w as o,s as r,I as n,x as l,a1 as i,A as p,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse(`{"title":"轻松使用“Explain Shell”脚本来理解 Shell 命令 | LCTT x X-CMD","titleTemplate":false,"description":"轻松使用“Explain Shell”脚本来理解 Shell 命令 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"轻松使用“Explain Shell”脚本来理解 Shell 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"轻松使用“Explain Shell”脚本来理解 Shell 命令 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150728 Understanding Shell Commands Easily Using 'Explain Shell' Script in Linux","title":"轻松使用“Explain Shell”脚本来理解 Shell 命令","tag":"201508","desc":""},"relativePath":"201508/20150728 Understanding Shell Commands Easily Using 'Explain Shell' Script in Linux.md","filePath":"[post].md"}`),h={name:"201508/20150728 Understanding Shell Commands Easily Using 'Explain Shell' Script in Linux.md"};function d(u,e,x,g,w,c){const t=s("Link");return o(),r("div",null,[e[16]||(e[16]=n("h1",{id:"轻松使用-explain-shell-脚本来理解-shell-命令",tabindex:"-1"},[l("轻松使用“Explain Shell”脚本来理解 Shell 命令 "),n("a",{class:"header-anchor",href:"#轻松使用-explain-shell-脚本来理解-shell-命令","aria-label":"Permalink to “轻松使用“Explain Shell”脚本来理解 Shell 命令”"},"​")],-1)),e[17]||(e[17]=n("p",null,"我们在Linux上工作时，每个人都会遇到需要查找shell命令的帮助信息的时候。 尽管内置的帮助像man pages、whatis命令有所助益， 但man pages的输出非常冗长， 除非是个有linux经验的人，不然从大量的man pages中获取帮助信息是非常困难的，而whatis命令的输出很少超过一行， 这对初学者来说是不够的。",-1)),e[18]||(e[18]=n("p",null,[n("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/07/Explain-Shell-Commands-in-Linux-Shell.jpeg",alt:"Explain Shell Commands in Linux Shell"})],-1)),e[19]||(e[19]=n("p",null,[n("em",null,"在Linux Shell中解释Shell命令")],-1)),n("p",null,[e[1]||(e[1]=l("有一些第三方应用程序， 像我们在",-1)),i(t,{href:"http://www.tecmint.com/cheat-command-line-cheat-sheet-for-linux-users/"},{default:p(()=>[...e[0]||(e[0]=[l("Linux 用户的命令行速查表",-1)])]),_:1}),e[2]||(e[2]=l("提及过的'cheat'命令。cheat是个优秀的应用程序，即使计算机没有联网也能提供shell命令的帮助， 但是它仅限于预先定义好的命令。",-1))]),e[20]||(e[20]=m(`<p>Jackson写了一小段代码，它能非常有效地在bash shell里面解释shell命令，可能最美之处就是你不需要安装第三方包了。他把包含这段代码的的文件命名为“explain.sh”。</p><h4 id="explain-sh工具的特性" tabindex="-1">explain.sh工具的特性 <a class="header-anchor" href="#explain-sh工具的特性" aria-label="Permalink to “explain.sh工具的特性”">​</a></h4><ul><li>易嵌入代码。</li><li>不需要安装第三方工具。</li><li>在解释过程中输出恰到好处的信息。</li><li>需要网络连接才能工作。</li><li>纯命令行工具。</li><li>可以解释bash shell里面的大部分shell命令。</li><li>无需使用root账户。</li></ul><p><strong>先决条件</strong></p><p>唯一的条件就是&#39;curl&#39;包了。 在如今大多数Linux发行版里面已经预安装了curl包， 如果没有你可以按照下面的命令来安装。</p><pre><code># apt-get install curl 	[On Debian systems]
# yum install curl 		[On CentOS systems]
</code></pre><h3 id="在linux上安装explain-sh工具" tabindex="-1">在Linux上安装explain.sh工具 <a class="header-anchor" href="#在linux上安装explain-sh工具" aria-label="Permalink to “在Linux上安装explain.sh工具”">​</a></h3><p>我们要将下面这段代码插入&#39;~/.bashrc&#39;文件（LCTT译注: 若没有该文件可以自己新建一个）中。我们要为每个用户以及对应的&#39;.bashrc&#39;文件插入这段代码，但是建议你不要加在root用户下。</p><p>我们注意到.bashrc文件的第一行代码以（#）开始， 这个是可选的并且只是为了区分余下的代码。</p><p># explain.sh 标记代码的开始， 我们将代码插入.bashrc文件的底部。</p><pre><code># explain.sh begins
explain () {
  if [ &quot;$#&quot; -eq 0 ]; then
    while read  -p &quot;Command: &quot; cmd; do
      curl -Gs &quot;https://www.mankier.com/api/explain/?cols=&quot;$(tput cols) --data-urlencode &quot;q=$cmd&quot;
    done
    echo &quot;Bye!&quot;
  elif [ &quot;$#&quot; -eq 1 ]; then
    curl -Gs &quot;https://www.mankier.com/api/explain/?cols=&quot;$(tput cols) --data-urlencode &quot;q=$1&quot;
  else
    echo &quot;Usage&quot;
    echo &quot;explain                  interactive mode.&quot;
    echo &quot;explain &#39;cmd -o | ...&#39;   one quoted command to explain it.&quot;
  fi
}
</code></pre><h3 id="explain-sh工具的使用" tabindex="-1">explain.sh工具的使用 <a class="header-anchor" href="#explain-sh工具的使用" aria-label="Permalink to “explain.sh工具的使用”">​</a></h3><p>在插入代码并保存之后，你必须退出当前的会话然后重新登录来使改变生效（LCTT译注：你也可以直接使用命令<code>source~/.bashrc</code> 来让改变生效）。每件事情都是交由‘curl’命令处理， 它负责将需要解释的命令以及命令选项传送给mankier服务，然后将必要的信息打印到Linux命令行。不必说的就是使用这个工具你总是需要连接网络。</p><p>让我们用explain.sh脚本测试几个笔者不懂的命令例子。</p><p><strong>1.我忘了‘du -h’是干嘛用的， 我只需要这样做:</strong></p><pre><code>$ explain &#39;du -h&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Get-Help-on-du-Command.png" alt="Get Help on du Command"></p><p><em>获得du命令的帮助</em></p><p><strong>2.如果你忘了&#39;tar -zxvf&#39;的作用，你可以简单地如此做:</strong></p><pre><code>$ explain &#39;tar -zxvf&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Tar-Command-Help.png" alt="Tar Command Help"></p><p><em>Tar命令帮助</em></p><p><strong>3.我的一个朋友经常对&#39;whatis&#39;以及&#39;whereis&#39;命令的使用感到困惑，所以我建议他：</strong></p><p>在终端简单的地敲下explain命令进入交互模式。</p><pre><code>$ explain
</code></pre><p>然后一个接着一个地输入命令，就能在一个窗口看到他们各自的作用：</p><pre><code>Command: whatis
Command: whereis
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Whatis-Whereis-Commands-Help.png" alt="Whatis Whereis Commands Help"></p><p><em>Whatis/Whereis命令的帮助</em></p><p>你只需要使用“Ctrl+c”就能退出交互模式。</p><p><strong>4. 你可以通过管道来请求解释更多的命令。</strong></p><pre><code>$ explain &#39;ls -l | grep -i Desktop&#39;
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/07/Get-Help-on-Multiple-Commands.png" alt="Get Help on Multiple Commands"></p><p><em>获取多条命令的帮助</em></p><p>同样地，你可以请求你的shell来解释任何shell命令。 前提是你需要一个可用的网络。输出的信息是基于需要解释的命令，从服务器中生成的，因此输出的结果是不可定制的。</p><p>对于我来说这个工具真的很有用，并且它已经荣幸地添加在我的.bashrc文件中。你对这个项目有什么想法？它对你有用么？它的解释令你满意吗？请让我知道吧！</p><p>请在下面评论为我们提供宝贵意见，喜欢并分享我们以及帮助我们得到传播。</p><hr>`,38)),n("p",null,[e[4]||(e[4]=l("via: ",-1)),i(t,{href:"http://www.tecmint.com/explain-shell-commands-in-the-linux-shell/"},{default:p(()=>[...e[3]||(e[3]=[l("http://www.tecmint.com/explain-shell-commands-in-the-linux-shell/",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=l("作者：",-1)),i(t,{href:"http://www.tecmint.com/author/avishek/"},{default:p(()=>[...e[5]||(e[5]=[l("Avishek Kumar",-1)])]),_:1}),e[9]||(e[9]=l(" 译者：",-1)),i(t,{href:"https://github.com/dingdongnigetou"},{default:p(()=>[...e[6]||(e[6]=[l("dingdongnigetou",-1)])]),_:1}),e[10]||(e[10]=l(" 校对：",-1)),i(t,{href:"https://github.com/wxy"},{default:p(()=>[...e[7]||(e[7]=[l("wxy",-1)])]),_:1})]),n("p",null,[e[13]||(e[13]=l("本文由 ",-1)),i(t,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[11]||(e[11]=[l("LCTT",-1)])]),_:1}),e[14]||(e[14]=l(" 原创翻译，",-1)),i(t,{href:"https://linux.cn/"},{default:p(()=>[...e[12]||(e[12]=[l("Linux中国",-1)])]),_:1}),e[15]||(e[15]=l(" 荣誉推出",-1))])])}const T=a(h,[["render",d]]);export{f as __pageData,T as default};
